changeSet.sql:
ALTER TABLE tenant_settings ADD COLUMN IF NOT EXISTS primary_color character varying(7); ALTER TABLE tenant_settings ADD COLUMN IF NOT EXISTS secondary_color character varying(7);
UPDATE tenant_settings settings SET primary_color = organization.primary_color FROM tenant_organization organization WHERE settings.tenant_organization_id = organization.id AND (settings.primary_color IS NULL OR btrim(settings.primary_color) = '') AND organization.primary_color IS NOT NULL AND btrim(organization.primary_color) <> '';
UPDATE tenant_settings settings SET secondary_color = organization.secondary_color FROM tenant_organization organization WHERE settings.tenant_organization_id = organization.id AND (settings.secondary_color IS NULL OR btrim(settings.secondary_color) = '') AND organization.secondary_color IS NOT NULL AND btrim(organization.secondary_color) <> '';
